INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370793, 15318, 'Navbharat Times', 'hi', 'ISI का शहजाद भट्टी नेटवर्क तबाह , अमित शाह ने खोली पोल तो बौखलाया पाकिस्तान , कुलभूषण का अलापा राग', 'https://navbharattimes.indiatimes.com/world/pakistan/pakistan-rejects-amit-shah-isi-shahzad-bhatti-terror-allegations-kulbhushan-jadhav/articleshow/133311609.cms', '', 'https://static.langimg.com/nbt/thumb/133311737/pakistan-foreign-office.jpg?imgsize=203137&resizemode=75', '20260818', '2026-08-18T07:35:29.006659'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370940, 15318, 'The Hindu', 'en', 'Pakistan rejects India’s remarks over Shahzad Bhatti terror network', 'https://www.thehindu.com/news/international/pakistan-rejects-indias-remarks-over-shahzad-bhatti-terror-network/article71359312.ece', 'According to the Centre, the Shahzad Bhatti Network is a Pakistan-based terror syndicate involved in grenade, IED and petrol-bomb attacks, and targeted killings across India', 'https://th-i.thgim.com/public/incoming/te7276/article71359332.ece/alternates/LANDSCAPE_1200/Shahzad%20Bhatti.jpg', '2026-08-18T07:30:08+00:00', '2026-08-18T08:17:29.375743'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371073, 15318, 'Aaj Tak', 'hi', 'अमित शाह के ISI वाले बयान पर पाकिस्तान बौखलाया, टेरर लिंक पर कही ये बात', 'https://www.aajtak.in/world/story/amit-shah-isi-remarks-pakistan-denies-links-shahzad-bhatti-network-ntc-mnrd-smsr-dskc-2624677-2026-08-18', 'केंद्रीय गृह मंत्री अमित शाह के ISI से जुड़े शाहजाद भट्टी नेटवर्क पर दिए बयान को लेकर पाकिस्तान ने तीखी प्रतिक्रिया दी है. पाकिस्तान ने भारत के आरोपों को बेबुनियाद बताया और कहा कि नई दिल्ली घरेलू सुरक्षा चुनौतियों से ध्यान भटकाने के लिए पाकिस्तान का नाम ले रही है. शाह ने 14 राज्यों में कार्रवाई के दौरान 200 से ज्यादा नेटवर्क ऑपरेटिव्स की गिरफ्तारी की बात कही थी.', '', '2026-08-18T07:54:05+00:00', '2026-08-18T08:18:32.287749'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
