INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370006, 15324, 'The Hindu', 'en', 'BJP’s Telangana snub shocks leaders, cadres; three senior leaders dropped, no representation in party’s new national team', 'https://www.thehindu.com/news/national/telangana/bjps-telangana-snub-shocks-leaders-cadres/article71357504.ece', 'Public disagreements, factional lobbying and social media attacks among State party leaders are said to have particularly annoyed the central leadership', 'https://th-i.thgim.com/public/incoming/b57sdb/article71359240.ece/alternates/LANDSCAPE_1200/25hyngg_NEC%20of%20the%20party%2001.jpg', '2026-08-18T06:47:10+00:00', '2026-08-18T07:26:22.364917'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
