INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370157, 15324, 'TFIPOST', 'en', 'The chemistry teacher who is now the BJP’s social media chief', 'https://tfipost.com/2026/08/the-chemistry-teacher-who-is-now-the-bjps-social-media-chief', 'Until this week, Deepak Mhaskey was known mainly within the Bharatiya Janata Party’s (BJP) Chhattisgarh unit, where he built the state’s district-level social media network and analysed election data for the party. He has now been named head of the BJP’s national IT cell, taking over from Amit Malviya, who ran the party’s digital operations […] The post The chemistry teacher who is now the BJP’s social media chief appeared first on Tfipost.com .', '', '2026-08-18T07:21:04+00:00', '2026-08-18T07:28:01.245508'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370936, 15324, 'The Hindu', 'en', 'Why Amit Malviya lost his job as BJP’s social media chief', 'https://www.thehindu.com/news/national/why-amit-malviya-lost-his-job-as-bjps-social-media-chief/article71359331.ece', 'While lip service was paid to the fact that there were as many kinds of Gen-Z as there were other social and economic communities, this segmentary approach was not adopted in the BJP’s online engagement', 'https://th-i.thgim.com/public/incoming/g1j9g7/article71359345.ece/alternates/LANDSCAPE_1200/PTI03_11_2025_000341B.jpg', '2026-08-18T07:39:30+00:00', '2026-08-18T08:17:29.317840'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
