INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (364279, 15326, 'The Guardian', 'en', 'Lindsay Clancy had ‘thoughts of harming the children’, mother testifies at trial', 'https://www.theguardian.com/us-news/2026/aug/17/lindsay-clancy-trial-mother-witness-testimony', 'Paula Musgrove stated her daughter had said medications were ‘destroying’ her mind and she was becoming ‘paranoid’ The defense in the Lindsay Clancy filicide case called the defendant’s mother as one of its first witnesses Monday, after three weeks of prosecution evidence laid out, in often harrowing detail, events surrounding Clancy’s killing of her three children. Under questioning from defense attorney David Reddington, Clancy’s mother, Paula Musgrove, testified that her daughter’s statements and actions had unsettled her in the months leading up to 24 January 2023. Continue reading...', 'https://i.guim.co.uk/img/media/9fcdb97b491c3c6d5b580b74c2d933ac9483d62d/0_61_3595_2877/master/3595.jpg?width=140&quality=85&auto=format&fit=max&s=43adbeab4128dc0d457eb814efa8cc4f', '2026-08-17T21:49:13+00:00', '2026-08-17T22:36:07.693875'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
