INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366820, 15336, 'Aaj Tak', 'hi', 'बीजेपी की टीम रिशफलिंग में छिपा है 2027 से 2029 तक का चुनावी प्लान! समझें कैसे', 'https://www.aajtak.in/elections/assembly-chunav/story/bjp-nitin-nabin-team-resufling-election-state-focus-youth-experience-mission-2029-ntcpkb-dskc-2624432-2026-08-18', 'बीजेपी के राष्ट्रीय अध्यक्ष नितिन नवीन द्वारा घोषित कार्यकारिणी के माध्यम से पार्टी ने 2027 के विधानसभा चुनावों से लेकर 2029 के लोकसभा चुनावों तक के लिए अपनी संगठनात्मक तैयारी मजबूत कर ली है. इस नई टीम में 51 नए चेहरों और वरिष्ठ नेताओं के समावेश के साथ-साथ क्षेत्रीय, सामाजिक और लैंगिक संतुलन साधने का प्रयास किया गया है.', '', '2026-08-18T03:39:03+00:00', '2026-08-18T03:59:36.160689'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
