INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369481, 15337, 'The Economic Times', 'en', 'European finances stare at major risk factor', 'https://economictimes.indiatimes.com/news/international/world-news/climate-damage-the-next-hit-to-europes-public-finances/articleshow/133313381.cms', 'LONDON: Someone will have to pick up the tab for the damage wrought by Europe''s increasingly volatile weather, and with the bulk of those economic losses uninsured, ​that will be the public purse unless immediate action is taken.This ​year''s wildfires in southwestern Europe and the severe flooding that hit Spain in 2024 and Germany and its neighbours in 2021 show how climate ​damage is adding to a list of strains on Europe''s finances that already includes higher defence spending and rising costs associated with an ageing population."The problem is that they''re becoming more recurrent," Federic', '', '2026-08-18T06:21:16+00:00', '2026-08-18T06:42:14.299984'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
